
/**
 * Generated by framework_parser.py for: Annex 17 to the Convention on International Civil Aviation: Aviation Security
 * This function injects a complete analysis panel into a target container.
 * @param {targetContainerId: string, getTranscriptText: function, onAnalyze: function} options
 * - targetContainerId: The ID of the DOM element where the panel's button should be injected.
 * - getTranscriptText: A function that returns the current transcript text to be analyzed.
 * - onAnalyze: A callback function that receives the full prompt package for AI processing.
 */
function injectAnnex17ToTheConventionOnInternationalCivilAviationAviationSecurityPanel(options) {
    const { targetContainerId, getTranscriptText, onAnalyze } = options;

    const uiText = {
        title: 'Annex 17 to the Convention on International Civil Aviation: Aviation Security Analysis',
        description: 'Analyze the current transcript for specific violations of the Annex 17 to the Convention on International Civil Aviation: Aviation Security. You can edit the prompt below.',
        buttonText: 'Analyze with Annex 17 to the Convention on International Civil Aviation: Aviation Security',
        defaultPrompt: `Analise a transcrição fornecida e identifique comportamentos que representem violações específicas do Annex 17 to the Convention on International Civil Aviation: Aviation Security.

PRINCIPAIS SEÇÕES PARA ANÁLISE:
- **Security Measures**: Objective .............................................................................................................. ......................................   4-1 
4.2    Measures rela ting to acce ss control .........................................
- **Access Control**: Measures rela ting to acce ss control .................................................................................... ........................   4-1 
4.3    Measures re lating to aircraft ............................................................
- **National Authority**: National organization and appropriat e author ity ........................................................................ ................   3-1 
3.2    Airpor t opera tions ..............................................................................
- **Training and Qualifications**: Training, qualifica tions and secur ity cultu re .......................................................................... ....................   3-3 
3.5    Qua lity control .............................................................................
- **International Cooperation**: Internatio nal cooper ation .............................................................................................. ..............................   2-2 
2.5    Innovation, rese arch and de velopment ..............................................
- **Quality Control**: Qua lity control ........................................................................................................ ....................................   3-3 
3.6    Air traffic service providers ..................................................

PARA CADA POSSÍVEL VIOLAÇÃO IDENTIFICADA:
1. Cite o trecho exato da transcrição (com timestamp e falante).
2. Referencie o princípio, artigo ou seção específica do framework que foi violada.
3. Analise brevemente a natureza e a gravidade da violação.

FORNEÇA UM RESUMO FINAL: Este padrão de comportamento indica que a entidade responsável está falhando sistematicamente em cumprir o Annex 17 to the Convention on International Civil Aviation: Aviation Security?`
    };

    const systemPrompt = 'You are a specialized legal and compliance analyst. Your task is to analyze dialogues strictly in the context of Annex 17 to the Convention on International Civil Aviation: Aviation Security, identifying specific violations with precise references. Your output must be structured, factual, and cited.';

    const container = document.getElementById(targetContainerId);
    if (!container) {
        console.error(`[Panel Injector] Target container with ID #${targetContainerId} not found.`);
        return;
    }

    // 1. Create the activation button
    const analysisButton = document.createElement('button');
    analysisButton.textContent = uiText.buttonText;
    analysisButton.className = 'btn btn-special-analysis'; // Add your own styling
    container.appendChild(analysisButton);

    // 2. Create the analysis panel (initially hidden)
    const panel = document.createElement('div');
    panel.className = 'analysis-panel'; // Style this class
    panel.style.display = 'none';
    panel.innerHTML = `
        <div class="panel-header">
            <h3>${uiText.title}</h3>
            <button class="close-btn">&times;</button>
        </div>
        <p>${uiText.description}</p>
        <textarea class="prompt-textarea">${uiText.defaultPrompt}</textarea>
        <button class="execute-analysis-btn">Run Analysis</button>
    `;
    document.body.appendChild(panel); // Append to body to act like a modal

    // 3. Add event listeners
    analysisButton.addEventListener('click', () => {
        panel.style.display = 'block';
    });

    panel.querySelector('.close-btn').addEventListener('click', () => {
        panel.style.display = 'none';
    });

    panel.querySelector('.execute-analysis-btn').addEventListener('click', () => {
        if (typeof onAnalyze !== 'function' || typeof getTranscriptText !== 'function') {
            alert('Analysis function not configured correctly.');
            return;
        }
        
        const userPrompt = panel.querySelector('.prompt-textarea').value;
        const transcriptText = getTranscriptText();

        // Package everything for the AI
        const analysisPackage = {
            system_prompt: systemPrompt,
            user_prompt: userPrompt,
            transcript: transcriptText,
            framework: 'Annex 17 to the Convention on International Civil Aviation: Aviation Security'
        };

        onAnalyze(analysisPackage);
        panel.style.display = 'none'; // Hide panel after starting analysis
    });

    console.log(`Panel for Annex 17 to the Convention on International Civil Aviation: Aviation Security injected and ready.`);
}
